// Existing TextDecoder entry-point reproduction for the actual native EOF
// witness generated by source_utf16_eof_probe.py. It fails before the Source
// UTF16 owner is connected and becomes an exact regression check afterward.
module main

import encoding
import libjs

fn main() {
	mut matches := true
	for big_endian in [false, true] {
		label := if big_endian { 'utf-16be' } else { 'utf-16le' }
		input := if big_endian { [u8(0xd8), 0, 0] } else { [u8(0), 0xd8, 0] }
		decoder := encoding.TextDecoder.construct(label, encoding.TextDecoderOptions{})!
		result := decoder.decode(input, encoding.TextDecodeOptions{})!
		owned := libjs.utf16_string_from_utf8_without_validation(result)
		units := owned.code_units()
		println('${label}: existing model units ${units}; native Source units [65533]')
		matches = matches && units == [u16(0xfffd)]
	}
	assert matches
}
